// file is referenced from plugin.json ("types") and read by the engine's
// /plugin-types generator, so it must not import anything.

export type Tier = 'fast' | 'balanced' | 'powerful'
export type Effort = 'low' | 'medium' | 'high' | 'max'
export type Source = 'jev' | 'builtin'

export interface TurnUsage {
  steps: number
  input: number
  cacheRead: number
  cacheWrite: number
  context: number
}

export interface Decision {
  tier: Tier
  requested: Tier
  effort: Effort
  confidence: number
  risky: number | null
  source: Source
  model: string
  rewrite?: boolean
  rewriteModel?: boolean
  locked?: boolean
  sessionModel?: string
  usage?: TurnUsage
  turnId?: string
  agentId?: string
  promptKey?: string
  latencyMs?: number
  at?: number
}

declare module 'claude-code' {
  interface PluginState {
    'jev-route': {
      /** Decisions for turns in flight, keyed by turnId (bound at turn.start, removed at turn.complete). */
      pending: Record<string, Decision>
      /** Decision composed at prompt.submit whose turnId is not yet known. */
      unbound: Decision | null
      /** Decision of the most recent completed main-agent turn (for /route status, previous_tier and the hysteresis anchor). */
      last: Decision | null
      /** Context size in tokens of the most recent main-agent request, from its turn.step result; null until one is seen. */
      context: number | null
    }
  }
}
